; ─────────────────────────────────────────────────────────
;  Load stage config for STAGE ($0D1F).
;  Sets SEQ_START ($0D11), SEQ_PTR ($0D13),
;  SEQ_RELOAD ($0D17) = (28 << byte[4]) + byte[3],
;  cube colour targets from config bytes[0/2].
; ─────────────────────────────────────────────────────────
SPAWN_SEQ_INIT:
  0000:ad70  MOV DI,0xaa81                             
  0000:ad73  MOV word ptr [0xbbb],0x0                  
  0000:ad79  JMP 0x0000:ad8d                           
  0000:ad7b  ?? 90h                                    
  0000:ad7c  MOV BL,byte ptr [0xd1f]                     ; BL = STAGE [0x0D1F]  (0..17)
  0000:ad80  XOR BH,BH                                 
  0000:ad82  CMP BX,0x12                                 ; STAGE >= 18?
  0000:ad85  JGE 0x0000:ad70                             ; yes: fallback to $AA81 config
  0000:ad87  SHL BX,0x1                                  ; BX *= 2  (pointer table is LE16 words)
  0000:ad89  MOV DI,word ptr [BX + 0xa899]               ; DI = STAGE_TABLE[STAGE]  (config struct ptr)
  0000:ad8d  PUSH SI                                   
